  beforeEach(() => {
    cy.visit('/notifications');
  });

  it('should announce interactive toast notifications with screen readers', () => {
    // Intercept the API call to fetch toast notifications
    cy.intercept('GET', '/api/notifications').as('getNotifications');
    cy.wait('@getNotifications');

