    cy.get('[data-testid="toast-close-btn"]').should('be.visible');

    // Verify toast has an action button
    cy.get('[data-testid="toast-action-btn"]').should('be.visible');

    // Verify toast has a dismiss button
    cy.get('[data-testid="toast-dismiss-btn"]').should('be.visible');

    // Verify toast has a timeout
    cy.get('[data-testid="toast-timeout"]').should('be.visible');

    // Verify toast has a role attribute for screen readers
    cy.get('[data-testid="toast-container"]').should('have.attr', 'role', 'alert');

    // Verify toast has aria-live attribute
    cy.get('[data-testid="toast-container"]').should('have.attr', 'aria-live', 'polite');

